function pageSignal(){pageController?.abort();pageController=new AbortController();return pageController.signal;}
function recommendLiterature({modal}){const rows=papers();modal('推荐文献',`<p class="hub-description">基于你已保存文献的标题、标签、阅读记录和笔记，生成本地相关推荐。结果来自当前浏览器，不代表在线数据库检索或真实推荐。</p><form id="lit-recommend-form" class="lit-recommend-form"><label for="lit-recommend-query">研究主题或关键词（可选）</label><div><input id="lit-recommend-query" maxlength="120" placeholder="例如：课堂反馈、机器学习、乡村振兴"><button class="btn primary" type="submit">生成推荐</button></div></form><div id="lit-recommend-results" class="lit-recommend-results">${recommendationRowsMarkup(rows)}</div><p class="hub-footnote">想获得更多候选？请先导入文献，或在文献库中补充标题与标签。</p>`);const form=$('#lit-recommend-form'),results=$('#lit-recommend-results');form.addEventListener('submit',e=>{e.preventDefault();results.innerHTML=recommendationRowsMarkup(rows,$('#lit-recommend-query').value);});}

function saveSearchMetadata(items,{isCurrent=()=>true,notify=()=>{}}={}){if(!isCurrent())throw Error('检索页面已关闭，请重新打开后添加。');const existing=papers(),fresh=newReferenceSearchItems(items,existing),now=new Date().toISOString();if(existing.length+fresh.length>200)throw Error('已保存 200 篇文献，请先整理不再需要的记录后重试。');const added=fresh.map(item=>validatePaper({...item,scope:'metadata',text:'',status:'unread',projectId:'',notes:[],warnings:[],createdAt:now,updatedAt:now}));if(!isCurrent())throw Error('检索页面已关闭，请重新打开后添加。');try{write(literatureKey,[...added,...existing]);}catch{throw Error('文献未能保存，当前选择仍保留，请稍后重试。');}notify(`已保存 ${added.length} 篇在线题录；全文尚未读取。`);return added;}
let discoveryInstance=null;
